input.command:
mkdir -p cmd/inspect && cat > dump.go <<'EOF'
// Package inspect provides deep pretty-printing of arbitrary Go values for
// debugging. It wraps github.com/davecgh/go-spew with debugging-friendly
// defaults: pointers are followed, cycles are detected, and map keys are
// sorted so output is stable across runs.
package inspect

import (
	"io"

	"github.com/davecgh/go-spew/spew"
)

// Config is the default configuration used by Dump, Sdump and Fdump.
var Config = &spew.ConfigState{
	Indent:                  "  ",
	SortKeys:                true, // deterministic map output
	DisablePointerAddresses: false,
	DisableCapacities:       false,
	ContinueOnMethod:        true, // show internals even if Stringer/error is implemented
	MaxDepth:                0,    // 0 = unlimited
}

// Dump writes a deep, annotated representation of each value to stdout.
func Dump(values ...any) { Config.Dump(values...) }

// Sdump returns a deep, annotated representation of each value as a string.
func Sdump(values ...any) string { return Config.Sdump(values...) }

// Fdump writes a deep, annotated representation of each value to w.
func Fdump(w io.Writer, values ...any) { Config.Fdump(w, values...) }
EOF
cat > dump_test.go <<'EOF'
package inspect

import (
	"strings"
	"testing"
)

type node struct {
	Name     string
	Children []*node
	Parent   *node
	meta     map[string]int
}

func TestSdumpNestedAndCyclic(t *testing.T) {
	root := &node{Name: "root", meta: map[string]int{"b": 2, "a": 1}}
	child := &node{Name: "child", Parent: root}
	root.Children = append(root.Children, child)

	out := Sdump(root)
	for _, want := range []string{`"root"`, `"child"`, "already shown", "meta:"} {
		if !strings.Contains(out, want) {
			t.Errorf("output missing %q:\n%s", want, out)
		}
	}
	if strings.Index(out, `"a"`) > strings.Index(out, `"b"`) {
		t.Errorf("map keys not sorted:\n%s", out)
	}
}
EOF
cat > cmd/inspect/main.go <<'EOF'
// Command inspect demonstrates deep pretty-printing of a sample structure.
package main

import (
	"errors"
	"time"

	"example.com/inspect"
)

type Config struct {
	Name    string
	Ports   []int
	Labels  map[string]string
	Timeout time.Duration
	Err     error
	Next    *Config
	private bool
}

func main() {
	c := &Config{
		Name:    "demo",
		Ports:   []int{80, 443},
		Labels:  map[string]string{"env": "dev", "app": "inspect"},
		Timeout: 3 * time.Second,
		Err:     errors.New("boom"),
		private: true,
	}
	c.Next = c // cycle
	inspect.Dump(c)
}
EOF
cat > .gitignore <<'EOF'
/inspect
*.test
*.out
EOF
gofmt -l . ; go mod tidy && go vet ./... && go test ./... && go run ./cmd/inspect

